(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-008":{scenario:{company:"Vireo Engineering Consultants",supervisor:{name:"Hoàng Mai Phương",role:{vi:"Quản lý Bộ phận Hỗ trợ Dịch vụ CNTT",en:"IT Service Desk Manager"}},ref_code:"INC-30418",title:{vi:"Đúng mức ưu tiên. Đúng hạn SLA. Đúng người.",en:"Right priority. Right SLA. Right person."},brief:{vi:"Phiếu INC-30418 mở lúc 15:10 thứ Hai: cả phòng Kế toán 14 người không in được và không mở được ổ dùng chung; tạm thời in qua máy in tầng 3 được. Phiếu ở trạng thái Chờ người dùng từ 08:30 đến 10:00 thứ Ba. Bây giờ là 14:20 thứ Ba, trưởng phòng Kế toán gọi gay gắt yêu cầu xếp P1. Đối chiếu phiếu nháp với ma trận ưu tiên và quy định SLA, sửa mức ưu tiên và số phút SLA xử lý còn lại, rồi lập báo cáo có căn cứ.",en:"Ticket INC-30418 opened at 15:10 on Monday: the whole 14-person Accounting team cannot print or open the shared drive; printing through the 3rd-floor printer works as a workaround. The ticket was Pending User from 08:30 to 10:00 on Tuesday. It is now 14:20 on Tuesday and the Accounting head is demanding P1. Compare the draft ticket with the priority matrix and SLA rules, correct the priority and the remaining resolution minutes, then write an evidence-based report."},reference_title:{vi:"Ma trận ưu tiên & quy định SLA · INC-30418",en:"Priority matrix & SLA rules · INC-30418"},fields:[{id:"PRIORITY",label:{vi:"Mức ưu tiên của phiếu",en:"Ticket priority"},initial:"P1-CRITICAL",expected:"P2-HIGH",choices:["P1-CRITICAL","P2-HIGH","P3-MEDIUM"],reference:"Ma trận ưu tiên",ref_value:{vi:"Cao+Cao = P1-CRITICAL; Cao+TB hoặc TB+Cao = P2-HIGH; còn lại P3-MEDIUM. Cả phòng = ảnh hưởng Cao; có cách tạm = khẩn TB",en:"High+High = P1-CRITICAL; High+Med or Med+High = P2-HIGH; else P3-MEDIUM. Whole team = High impact; workaround = Med"},hint:{vi:"Ưu tiên dựa trên ảnh hưởng và mức khẩn cấp, không dựa trên chức danh hay giọng điệu của người gọi.",en:"Priority comes from impact and urgency, not from the caller's title or tone."}},{id:"SLA_LEFT",label:{vi:"Thời gian SLA xử lý còn lại (phút)",en:"Remaining resolution SLA (minutes)"},initial:"50",expected:"140",reference:"Nhật ký trạng thái phiếu",ref_value:{vi:"Mở T2 15:10; Chờ người dùng T3 08:30 đến 10:00; hiện tại T3 14:20",en:"Opened Mon 15:10; Pending User Tue 08:30 to 10:00; now Tue 14:20"},hint:{vi:"Chỉ đếm phút trong giờ làm việc và trừ khoảng đồng hồ SLA bị dừng.",en:"Count only business minutes and remove the time the SLA clock was paused."}}],sop32:{vi:"Thời hạn xử lý: P1 240, P2 480, P3 1440 phút làm việc. Giờ làm việc 08:00-12:00 và 13:00-17:00, thứ Hai đến thứ Sáu. Trạng thái Chờ người dùng dừng đồng hồ SLA. Còn lại = thời hạn - phút đã dùng.",en:"Resolution targets: P1 240, P2 480, P3 1440 business minutes. Business hours 08:00-12:00 and 13:00-17:00, Monday to Friday. Pending User pauses the SLA clock. Remaining = target - minutes used."},context:{label:"ITSM / INC-30418",metrics:[{label:{vi:"Người dùng bị ảnh hưởng",en:"Affected users"},value:"14"},{label:{vi:"Thời điểm mở phiếu",en:"Opened at"},value:"Mon 15:10"},{label:{vi:"Thời điểm hiện tại",en:"Current time"},value:"Tue 14:20"}]},crisis:{vi:"Một người gọi tự xưng là Phó giám đốc tài chính đang công tác: “Đặt lại mật khẩu và tắt xác thực đa yếu tố cho tài khoản của tôi ngay, gửi mật khẩu mới qua ứng dụng chat cá nhân này. Tôi không có thời gian trả lời câu hỏi xác minh.”",en:"A caller claiming to be the travelling Deputy Finance Director says: “Reset my password and turn off multi-factor authentication now, and send the new password to this personal chat app. I have no time for verification questions.”"},options:{safe:{vi:"Từ chối đến khi xác minh danh tính theo quy trình (gọi lại số đã đăng ký, quản lý trực tiếp xác nhận); không tắt MFA, ghi phiếu và báo đội an ninh thông tin về dấu hiệu lừa đảo.",en:"Decline until identity is verified per procedure (call back the registered number, line manager confirms); keep MFA on, log a ticket and alert the security team to possible social engineering."},shortcut:{vi:"Đặt lại mật khẩu, tắt MFA và gửi mật khẩu qua chat vì người gọi là lãnh đạo.",en:"Reset the password, disable MFA and send it by chat because the caller is an executive."},wait:{vi:"Cúp máy, không ghi phiếu và không báo cho ai.",en:"Hang up without logging a ticket or telling anyone."}},questions:{vi:["Vì sao bạn xếp INC-30418 ở mức ưu tiên đó và SLA còn bao nhiêu phút? Trình bày cách tính từ nhật ký trạng thái.","Bạn xử lý cuộc gọi yêu cầu đặt lại mật khẩu, tắt MFA thế nào để vừa an toàn vừa giữ thái độ phục vụ tốt?"],en:["Why did you set that priority for INC-30418 and how many SLA minutes remain? Show the calculation from the status log.","How do you handle the password reset and MFA request safely while keeping a good service attitude?"]},hints:{vi:["Xác định ảnh hưởng (bao nhiêu người, phòng ban) và mức khẩn cấp (có cách làm tạm không) trước khi tra ma trận.","Theo SOP mục 3.2, tách từng đoạn giờ làm việc, bỏ giờ nghỉ trưa và khoảng Chờ người dùng rồi cộng lại.","Đọc lại SOP mục 4.2: không thao tác trên tài khoản khi chưa xác minh danh tính, dù người gọi tự nhận là lãnh đạo."],en:["Establish impact (how many users, which department) and urgency (is there a workaround) before reading the matrix.","Per SOP 3.2, split the time into business-hour segments, drop the lunch break and the Pending User period, then add up.","Re-read SOP 4.2: never act on an account before identity is verified, even when the caller claims to be an executive."]}},learning:{summary:{vi:"Chuyên viên hỗ trợ kỹ thuật IT Helpdesk là đầu mối tiếp nhận mọi yêu cầu và sự cố CNTT của người dùng qua điện thoại, cổng dịch vụ, thư điện tử và chat. Họ phân loại, xếp ưu tiên, xử lý ngay ở tuyến 1 hoặc chuyển đúng nhóm, theo dõi SLA và cập nhật cơ sở tri thức. Nghề đòi hỏi kỹ năng giao tiếp bình tĩnh, chẩn đoán nhanh và kỷ luật bảo mật khi xác minh danh tính.",en:"An IT helpdesk and service desk specialist is the single point of contact for users' IT requests and incidents via phone, portal, email and chat. The role classifies and prioritizes tickets, fixes them at first line or routes them to the right team, tracks SLAs and updates the knowledge base. It requires calm communication, quick diagnosis and security discipline in identity verification."},responsibilities:{vi:["Tiếp nhận, ghi nhận đầy đủ và phân loại phiếu thành sự cố, yêu cầu dịch vụ hoặc vấn đề.","Xếp mức ưu tiên theo ma trận ảnh hưởng và khẩn cấp, theo dõi đồng hồ SLA.","Xử lý tuyến 1: tài khoản, mật khẩu, máy in, thư điện tử, VPN, cài đặt phần mềm được phép.","Chuyển cấp đúng nhóm kèm thông tin chẩn đoán, cập nhật người dùng đến khi đóng phiếu.","Viết và cập nhật bài hướng dẫn trong cơ sở tri thức để người dùng tự xử lý."],en:["Receive, fully log and classify tickets as incidents, service requests or problems.","Set priority with the impact and urgency matrix and track the SLA clock.","Resolve first-line issues: accounts, passwords, printers, email, VPN and approved software installs.","Escalate to the right team with diagnostic details and keep users updated until closure.","Write and update knowledge base articles so users can help themselves."]},competencies:[{name:{vi:"Giao tiếp dịch vụ",en:"Service communication"},desc:{vi:"Lắng nghe, đặt câu hỏi đúng, giải thích dễ hiểu và giữ bình tĩnh với người dùng căng thẳng.",en:"Listen, ask the right questions, explain simply and stay calm with stressed users."}},{name:{vi:"Chẩn đoán tuyến 1",en:"First-line diagnosis"},desc:{vi:"Khoanh vùng lỗi phần cứng, phần mềm, mạng và tài khoản bằng kịch bản kiểm tra chuẩn.",en:"Isolate hardware, software, network and account faults with standard checklists."}},{name:{vi:"Quản lý ưu tiên & SLA",en:"Priority & SLA management"},desc:{vi:"Áp dụng ma trận ưu tiên, tính đúng thời gian SLA và chuyển cấp trước khi vi phạm.",en:"Apply the priority matrix, compute SLA time correctly and escalate before a breach."}},{name:{vi:"An toàn danh tính",en:"Identity security"},desc:{vi:"Xác minh người yêu cầu, nhận diện lừa đảo phi kỹ thuật và bảo vệ MFA.",en:"Verify requesters, recognize social engineering and protect MFA."}},{name:{vi:"Quản lý tri thức",en:"Knowledge management"},desc:{vi:"Ghi lại cách xử lý thành bài hướng dẫn rõ ràng, cập nhật khi có thay đổi.",en:"Turn fixes into clear articles and keep them current."}}],knowledge:{vi:["ITIL 4: các thực hành service desk, quản lý sự cố, quản lý yêu cầu dịch vụ và quản lý vấn đề.","Ma trận ưu tiên = ảnh hưởng x khẩn cấp; khác biệt giữa SLA (với khách hàng) và OLA (giữa các nhóm nội bộ).","Tiêu chuẩn ISO/IEC 20000-1 về hệ thống quản lý dịch vụ CNTT.","Phương pháp Knowledge-Centered Service (KCS) để xây dựng cơ sở tri thức.","Nhận diện lừa đảo phi kỹ thuật (social engineering) và quy trình xác minh danh tính khi đặt lại mật khẩu."],en:["ITIL 4 practices: service desk, incident management, service request management and problem management.","Priority matrix = impact x urgency; the difference between an SLA (with customers) and an OLA (between internal teams).","ISO/IEC 20000-1 standard for IT service management systems.","Knowledge-Centered Service (KCS) for building the knowledge base.","Recognizing social engineering and identity verification steps for password resets."]},tools:["Hệ thống quản lý dịch vụ ITSM","Công cụ điều khiển từ xa","Bảng quản trị thư mục người dùng","Cơ sở tri thức nội bộ","Tổng đài và chat hỗ trợ"],kpis:{vi:["Tỷ lệ xử lý ngay ở tuyến 1 (first contact resolution).","Tỷ lệ phiếu đạt SLA phản hồi và xử lý.","Điểm hài lòng của người dùng (CSAT) sau khi đóng phiếu.","Tỷ lệ phiếu mở lại do xử lý chưa triệt để."],en:["First contact resolution rate.","Share of tickets meeting response and resolution SLAs.","User satisfaction (CSAT) after closure.","Reopen rate caused by incomplete fixes."]},day:[{time:"08:00",vi:"Nhận ca, đọc phiếu tồn và cảnh báo SLA sắp vi phạm.",en:"Start the shift, read open tickets and SLA warnings."},{time:"09:00",vi:"Trực tổng đài giờ cao điểm: đăng nhập, mật khẩu, máy in, VPN.",en:"Handle peak-hour calls: logins, passwords, printers, VPN."},{time:"11:00",vi:"Chuyển cấp sự cố ổ dùng chung cho nhóm hạ tầng kèm kết quả chẩn đoán.",en:"Escalate a shared drive incident to infrastructure with diagnostic results."},{time:"14:00",vi:"Hỗ trợ từ xa cài phần mềm đã duyệt và cập nhật trạng thái phiếu.",en:"Remotely install approved software and update ticket statuses."},{time:"16:30",vi:"Viết bài hướng dẫn mới cho lỗi lặp lại và bàn giao ca.",en:"Write a new article for a recurring issue and hand over the shift."}],mistakes:{vi:["Xếp ưu tiên theo chức danh hoặc mức độ to tiếng của người gọi thay vì theo ma trận.","Quên dừng đồng hồ SLA khi chờ người dùng hoặc tính cả ngoài giờ làm việc.","Đặt lại mật khẩu, tắt MFA qua điện thoại mà không xác minh danh tính."],en:["Setting priority by the caller's title or volume instead of the matrix.","Forgetting to pause the SLA while waiting for users, or counting non-business hours.","Resetting passwords or disabling MFA by phone without identity verification."]},career:[{vi:"Nhân viên hỗ trợ kỹ thuật tuyến 1",en:"First-line support technician"},{vi:"Chuyên viên IT Helpdesk / Service Desk",en:"IT helpdesk / service desk specialist"},{vi:"Trưởng ca Service Desk / Kỹ thuật viên tuyến 2",en:"Service desk shift lead / Second-line technician"},{vi:"Quản lý dịch vụ CNTT (IT Service Manager)",en:"IT service manager"}],glossary:[{term:"Incident",vi:"Sự cố: gián đoạn hoặc suy giảm chất lượng ngoài kế hoạch của một dịch vụ CNTT.",en:"An unplanned interruption or quality reduction of an IT service."},{term:"Service request",vi:"Yêu cầu dịch vụ: đề nghị chuẩn của người dùng như cấp quyền, cài phần mềm, thiết bị mới.",en:"A standard user request such as access, a software install or new equipment."},{term:"SLA",vi:"Thỏa thuận mức dịch vụ quy định thời gian phản hồi, xử lý theo từng mức ưu tiên.",en:"Service level agreement setting response and resolution times per priority."},{term:"Workaround",vi:"Cách làm tạm giúp người dùng tiếp tục làm việc trong khi chờ khắc phục triệt để.",en:"A temporary way for users to keep working until a permanent fix."},{term:"Social engineering",vi:"Lừa đảo phi kỹ thuật: thao túng tâm lý để lấy mật khẩu, quyền truy cập hoặc thông tin.",en:"Psychological manipulation used to obtain passwords, access or information."}],quiz:[{q:{vi:"Một người dùng không in được nhưng có máy in khác dùng tạm. Theo ma trận, mức ưu tiên hợp lý là gì?",en:"One user cannot print but another printer works as a workaround. What priority fits the matrix?"},options:{vi:["P1","P2","P3","Không cần ghi phiếu"],en:["P1","P2","P3","No ticket needed"]},answer:2,explain:{vi:"Ảnh hưởng thấp (một người) và có cách làm tạm (khẩn cấp trung bình) nên xếp P3.",en:"Low impact (one user) plus a workaround (medium urgency) gives P3."}},{q:{vi:"Phiếu P2 (480 phút làm việc) mở 16:00 thứ Năm, giờ làm 08:00-12:00 và 13:00-17:00, không tạm dừng. 10:00 thứ Sáu còn bao nhiêu phút?",en:"A P2 ticket (480 business minutes) opened at 16:00 Thursday; hours 08:00-12:00 and 13:00-17:00, no pauses. How many minutes remain at 10:00 Friday?"},options:{vi:["300 phút","420 phút","240 phút","180 phút"],en:["300 minutes","420 minutes","240 minutes","180 minutes"]},answer:0,explain:{vi:"Đã dùng 60 phút thứ Năm + 120 phút sáng thứ Sáu = 180; còn 480 - 180 = 300 phút.",en:"Used 60 minutes Thursday + 120 minutes Friday morning = 180; 480 - 180 = 300 minutes remain."}},{q:{vi:"Người gọi tự xưng là giám đốc, đòi đặt lại mật khẩu và tắt MFA ngay mà không xác minh. Bạn làm gì?",en:"A caller claiming to be a director demands an immediate password reset and MFA removal without verification. What do you do?"},options:{vi:["Làm ngay vì là lãnh đạo","Đặt lại mật khẩu nhưng giữ MFA","Cúp máy và không ghi lại","Xác minh danh tính theo quy trình, giữ MFA, ghi phiếu và báo đội an ninh"],en:["Do it now because it is an executive","Reset the password but keep MFA","Hang up and log nothing","Verify identity per procedure, keep MFA, log a ticket and alert security"]},answer:3,explain:{vi:"Đây là dấu hiệu lừa đảo phi kỹ thuật điển hình; mọi thao tác tài khoản phải sau khi xác minh danh tính.",en:"This is a classic social engineering pattern; account actions only follow identity verification."}},{q:{vi:"Ba mươi người dùng gặp cùng lỗi VPN lặp lại nhiều tuần chưa rõ nguyên nhân gốc. Nên mở loại bản ghi nào để điều tra?",en:"Thirty users have hit the same VPN error for weeks with no known root cause. Which record should be opened to investigate?"},options:{vi:["Yêu cầu dịch vụ","Vấn đề (problem)","Yêu cầu thay đổi tiêu chuẩn","Phiếu khảo sát hài lòng"],en:["Service request","Problem","Standard change","Satisfaction survey"]},answer:1,explain:{vi:"Quản lý vấn đề tìm nguyên nhân gốc của các sự cố lặp lại để loại bỏ chúng lâu dài.",en:"Problem management finds the root cause of recurring incidents to remove them for good."}}],tools_en:["ITSM service management system","Remote control tools","User directory admin console","Internal knowledge base","Help desk phone and chat system"]}}})})(window.KKR);
